-- supabase/sql/exam_question_bank_mht_cet_set1.sql
--
-- First curated question-bank batch for 'MHT-CET' (see exam_patterns_mht_cet.sql for the exam's
-- structure). Same exam_question_bank table/schema as the other sets -- no migration needed.
--
-- Like NEET/BITSAT (and unlike the JEE sets), MHT-CET's real format is 100% single-best-response
-- MCQ (4 options, exactly one correct) -- no multi-correct, numerical, or descriptive format in
-- the actual exam. 16 chapters (5 Physics, 5 Chemistry, 6 Mathematics) each get 4 classic,
-- NCERT/Maharashtra-board-level questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_mht_cet.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Physics: Mechanics
('MHT-CET', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The SI unit of angular momentum is:',
 '[{"text":"kg m/s","isCorrect":false},{"text":"kg m^2/s","isCorrect":true},{"text":"kg m/s^2","isCorrect":false},{"text":"kg m^2/s^2","isCorrect":false}]'::jsonb,
 null, 'Angular momentum L = I*omega (or r x p) has units of kg m^2/s, combining moment of inertia (kg m^2) with angular velocity (1/s).'),
('MHT-CET', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The center of mass of a uniform circular ring lies:',
 '[{"text":"On the ring itself","isCorrect":false},{"text":"At the geometric center of the ring","isCorrect":true},{"text":"Outside the plane of the ring","isCorrect":false},{"text":"At one-quarter of the radius from the center","isCorrect":false}]'::jsonb,
 null, 'By symmetry, the center of mass of a uniform ring lies at its geometric center, even though no material of the ring exists at that exact point.'),
('MHT-CET', 'Physics', 'Mechanics', 'easy', 'mcq',
 'A rigid body is said to be in mechanical equilibrium when:',
 '[{"text":"Its net force is zero, regardless of net torque","isCorrect":false},{"text":"Both net force and net torque acting on it are zero","isCorrect":true},{"text":"Its net torque is zero, regardless of net force","isCorrect":false},{"text":"It is moving with constant non-zero acceleration","isCorrect":false}]'::jsonb,
 null, 'A rigid body is in complete mechanical equilibrium only when both the net external force and the net external torque on it are zero.'),
('MHT-CET', 'Physics', 'Mechanics', 'easy', 'mcq',
 'As we go higher above the Earth''s surface, the value of acceleration due to gravity g:',
 '[{"text":"Increases","isCorrect":false},{"text":"Decreases","isCorrect":true},{"text":"Remains constant","isCorrect":false},{"text":"First increases, then decreases","isCorrect":false}]'::jsonb,
 null, 'Since g = GM/r^2, as the distance r from the Earth''s center increases with altitude, g decreases.'),

-- Physics: Electrodynamics
('MHT-CET', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'The equivalent resistance of two resistors R1 and R2 connected in parallel is:',
 '[{"text":"R1 + R2","isCorrect":false},{"text":"(R1*R2)/(R1+R2)","isCorrect":true},{"text":"(R1+R2)/2","isCorrect":false},{"text":"R1 - R2","isCorrect":false}]'::jsonb,
 null, 'For resistors in parallel, 1/R_eq = 1/R1 + 1/R2, which simplifies to R_eq = (R1*R2)/(R1+R2).'),
('MHT-CET', 'Physics', 'Electrodynamics', 'easy', 'mcq',
 'The direction of an induced current in a circuit is given by:',
 '[{"text":"Coulomb''s law","isCorrect":false},{"text":"Lenz''s law","isCorrect":true},{"text":"Ohm''s law","isCorrect":false},{"text":"Ampere''s law","isCorrect":false}]'::jsonb,
 null, 'Lenz''s law states that the induced current flows in a direction that opposes the change in magnetic flux that produced it.'),
('MHT-CET', 'Physics', 'Electrodynamics', 'easy', 'mcq',
 'Coulomb''s law describes the electrostatic force between:',
 '[{"text":"Two point charges","isCorrect":true},{"text":"A charge and a magnetic field","isCorrect":false},{"text":"Two current-carrying wires","isCorrect":false},{"text":"A charge and a neutral object only","isCorrect":false}]'::jsonb,
 null, 'Coulomb''s law gives the electrostatic force between two point charges as proportional to the product of the charges and inversely proportional to the square of the distance between them.'),
('MHT-CET', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'The SI unit of electric field intensity is:',
 '[{"text":"N/C","isCorrect":true},{"text":"C/N","isCorrect":false},{"text":"J/C","isCorrect":false},{"text":"C*m","isCorrect":false}]'::jsonb,
 null, 'Electric field intensity, defined as force per unit charge, has SI unit newton per coulomb (N/C), equivalent to volt per meter (V/m).'),

